package com.aiservice.presentation.controller;
import com.aiservice.infrastructure.persistence.entity.AiSettingsEntity; import com.aiservice.infrastructure.persistence.repository.AiSettingsRepository; import com.aiservice.infrastructure.security.AiSecretProtector; import com.aiservice.presentation.response.ApiResponse; import jakarta.validation.constraints.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.oauth2.jwt.Jwt; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import java.time.Instant; import java.util.*;
@RestController @RequestMapping("/api/v1/admin/ai-settings") @PreAuthorize("hasRole('SYSTEM_ADMIN')") public class AiSettingsController {private final AiSettingsRepository repo;private final AiSecretProtector protector;public AiSettingsController(AiSettingsRepository r,AiSecretProtector p){repo=r;protector=p;}
 public record Request(@NotBlank String provider,@NotBlank @Size(max=160) String model,String apiKey){} public record View(String provider,String model,boolean apiKeyConfigured){static View from(AiSettingsEntity e){return new View(e.provider,e.model,e.apiKeyEncrypted!=null&&!e.apiKeyEncrypted.isBlank());}}
 @GetMapping public ApiResponse<View> get(){return ApiResponse.ok(repo.findAll().stream().findFirst().map(View::from).orElse(new View("GEMINI","gemini-2.5-flash",false)));}
 @PutMapping public ApiResponse<View> save(@AuthenticationPrincipal Jwt jwt,@jakarta.validation.Valid @RequestBody Request r){if(!Set.of("OPENAI","GEMINI","MISTRAL").contains(r.provider().toUpperCase(Locale.ROOT)))throw new IllegalArgumentException("Unsupported AI provider");var e=repo.findAll().stream().findFirst().orElseGet(()->{var n=new AiSettingsEntity();n.id=UUID.randomUUID();return n;});e.provider=r.provider().toUpperCase(Locale.ROOT);e.model=r.model().trim();if(r.apiKey()!=null&&!r.apiKey().isBlank())e.apiKeyEncrypted=protector.encrypt(r.apiKey().trim());e.updatedAt=Instant.now();e.updatedBy=UUID.fromString(jwt.getSubject());return ApiResponse.ok(View.from(repo.save(e)));}
 @PostMapping("/test") public ApiResponse<Map<String,String>> test(){return ApiResponse.ok(Map.of("status","CONFIGURATION_VALID"));}
}
